"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { TextInput } from "@/app/_components/TextInput";
import type { ProcessEvent, SeedFile } from "@/app/features/sub_dev/DevTypes";
import { draftStorageKey, encodeDraft, decodeDraft, type LiveWorkDraft } from "./liveWorkDraft";

// Live Work Surface (moonshot E) — an in-product editor over the materialized seed.
// As the candidate works, it records OBSERVED process events (which files they
// open, edit, and decision-log entries) and flushes them + the file tree to the
// session. The engine then grades the judgment we WATCHED, not a reconstructed git
// log. We observe process artifacts only — never keystrokes or the screen.

const DECISIONS_FILE = "DECISIONS.md";
const FLUSH_MS = 8000;
const EDIT_DEBOUNCE_MS = 600;

export function LiveWorkSurface({ token, seedFiles, note }: { token: string; seedFiles: SeedFile[]; note: string | null }) {
  const t = useTranslations("devApply.workSurface");
  const [files, setFiles] = useState<SeedFile[]>(() => seedFiles.map((f) => ({ ...f })));
  const [activePath, setActivePath] = useState<string>(seedFiles[0]?.path ?? "");
  const [status, setStatus] = useState<"idle" | "submitting" | "submitted" | "error">("idle");

  // Identity (UAT M9): the live-work surface is the SOLE submit path for workspace
  // cases now, so it collects who to reach — a winning evaluation with no address
  // is an unreachable candidate. Labels reuse the repo-form's `devApply` keys.
  const tApply = useTranslations("devApply");
  const [name, setName] = useState("");
  const [contact, setContact] = useState("");
  const contactValid = /\S+@\S+\.\S+/.test(contact.trim());
  const canSubmit = name.trim().length > 0 && contactValid && status !== "submitting";

  const sessionIdRef = useRef<string | null>(null);
  const startingRef = useRef(false);
  const submittingRef = useRef(false);
  const pendingRef = useRef<ProcessEvent[]>([]);
  const filesRef = useRef(files);

  // Local draft persistence (verifier pass, 2026-07-17 — see DECISIONS.md). The
  // server flush (below) is the system of record, but it only lands every FLUSH_MS
  // and can fail for minutes at a time on a flaky connection. localStorage is the
  // durable copy that survives a reload, a crashed tab, or an offline gap regardless
  // of whether a flush ever reached the server — read once on mount, written on
  // every change. Scoped per apply-token so a shared device never bleeds one
  // candidate's draft into another's case.
  const [restored, setRestored] = useState(false);
  const persistDraft = useCallback(() => {
    if (typeof window === "undefined") return;
    try {
      const draft: LiveWorkDraft = {
        sessionId: sessionIdRef.current,
        files: filesRef.current,
        pending: pendingRef.current,
        savedAt: Date.now(),
      };
      window.localStorage.setItem(draftStorageKey(token), encodeDraft(draft));
    } catch {
      // localStorage can throw (quota exceeded, private-browsing lockout) — this is
      // a best-effort backstop, not the only copy of the work. Swallow and continue;
      // the in-memory buffer + periodic server flush still apply.
    }
  }, [token]);

  useEffect(() => {
    // Keep the ref current for the flush callback without re-creating the interval
    // on every keystroke. Synced in an effect (not during render) per react-hooks/refs.
    filesRef.current = files;
    persistDraft();
  }, [files, persistDraft]);

  // Resume-on-mount: runs once, client-only (localStorage doesn't exist during the
  // server render, and reading it during render would also desync SSR/CSR markup).
  // A brief flash from seed -> restored content on mount is an accepted tradeoff
  // (see DECISIONS.md) — silent, permanent data loss is the worse failure mode.
  useEffect(() => {
    if (typeof window === "undefined") return;
    const draft = decodeDraft(window.localStorage.getItem(draftStorageKey(token)));
    if (!draft) return;
    if (draft.files.length > 0) setFiles(draft.files);
    if (draft.sessionId) sessionIdRef.current = draft.sessionId;
    pendingRef.current = draft.pending;
    if (draft.files.length > 0 || draft.pending.length > 0) setRestored(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- run once on mount only
  }, []);

  const editTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Lazily mint the session on first interaction — never orphan a session for a
  // visitor who only reads the brief.
  const ensureSession = useCallback(async (): Promise<string | null> => {
    if (sessionIdRef.current) return sessionIdRef.current;
    if (startingRef.current) return null;
    startingRef.current = true;
    try {
      const r = await fetch("/api/devcase/session", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token }),
      });
      if (!r.ok) return null;
      const data = (await r.json()) as { sessionId?: string };
      sessionIdRef.current = data.sessionId ?? null;
      return sessionIdRef.current;
    } catch {
      return null;
    } finally {
      startingRef.current = false;
    }
  }, [token]);

  const record = useCallback(
    (kind: ProcessEvent["kind"], path?: string, size?: number) => {
      pendingRef.current.push({ t: Date.now(), kind, path, size });
      persistDraft();
      void ensureSession();
    },
    [ensureSession, persistDraft]
  );

  const flush = useCallback(
    async (opts?: { submit?: boolean }) => {
      const sid = await ensureSession();
      if (!sid) return;
      const batch = pendingRef.current;
      pendingRef.current = [];
      try {
        const r = await fetch(`/api/devcase/session/${sid}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ events: batch, files: filesRef.current }),
          keepalive: opts?.submit,
        });
        if (r.status === 404 || r.status === 409) {
          // This session id is dead — either the row is gone (rare, e.g. a DB
          // reset) or it was already submitted (a race: another tab/device for
          // the same draft got there first). Retrying the SAME id forever would
          // spin without ever landing. Drop it so the next ensureSession() mints
          // a fresh one; the batch and the file tree are still good, they just
          // need a new session to flush into.
          sessionIdRef.current = null;
          pendingRef.current = batch.concat(pendingRef.current);
          persistDraft();
          return;
        }
        if (!r.ok) throw new Error("flush failed");
        persistDraft();
      } catch {
        // Network failure (offline, timeout, flaky wifi) — re-buffer so an unsent
        // batch isn't lost, and persist it locally too: the next FLUSH_MS tick
        // retries automatically once the connection returns, and if the tab
        // closes first the draft survives in localStorage regardless.
        pendingRef.current = batch.concat(pendingRef.current);
        persistDraft();
      }
    },
    [ensureSession, persistDraft]
  );

  useEffect(() => {
    const iv = setInterval(() => void flush(), FLUSH_MS);
    return () => {
      clearInterval(iv);
      if (editTimer.current) clearTimeout(editTimer.current);
    };
  }, [flush]);

  function selectFile(path: string) {
    if (path === activePath) return;
    setActivePath(path);
    record("open", path);
  }

  function onEdit(path: string, contents: string) {
    setFiles((prev) => prev.map((f) => (f.path === path ? { ...f, contents } : f)));
    if (editTimer.current) clearTimeout(editTimer.current);
    editTimer.current = setTimeout(() => {
      record(path.endsWith(DECISIONS_FILE) ? "decision_log" : "edit", path);
    }, EDIT_DEBOUNCE_MS);
  }

  async function submit() {
    // Synchronous in-flight guard: setStatus is async, so a fast double Enter/click
    // could dispatch two POSTs before the button visibly disables. The ref flips
    // immediately, so a second call is a no-op until this one settles; reset in the
    // finally so an error is retryable (on success the submit button is gone anyway).
    if (submittingRef.current || !canSubmit) return;
    submittingRef.current = true;
    setStatus("submitting");
    record("submit", activePath);
    try {
      await flush({ submit: true });
      const sid = sessionIdRef.current;
      if (!sid) {
        setStatus("error");
        return;
      }
      const r = await fetch(`/api/devcase/session/${sid}/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ candidate: name.trim(), contact: contact.trim() }),
      }).catch(() => null);
      const ok = !!(r && r.ok);
      setStatus(ok ? "submitted" : "error");
      if (ok && typeof window !== "undefined") {
        // A submitted draft is done — clear it so a later visit to this same
        // link (or device) never resurrects an already-submitted attempt.
        try {
          window.localStorage.removeItem(draftStorageKey(token));
        } catch {
          // best-effort cleanup only
        }
      }
    } finally {
      submittingRef.current = false;
    }
  }

  const active = files.find((f) => f.path === activePath) ?? files[0];

  if (status === "submitted") {
    return (
      <section className="mt-6 rounded-lg border border-emerald-200 bg-emerald-50 p-5">
        <h2 className="font-serif text-h3 text-emerald-900">{t("submittedTitle")}</h2>
        <p className="mt-1 text-sm text-emerald-800">{t("submitted")}</p>
      </section>
    );
  }

  return (
    <section className="mt-6 rounded-lg border border-stone-200 bg-white p-5 shadow-panel">
      <h2 className="font-serif text-h3 text-ink">{t("heading")}</h2>
      <p className="mt-1 max-w-prose text-sm text-steel">{t("intro")}</p>
      {note ? <p className="mt-2 text-xs text-stone-400">{note}</p> : null}
      {restored ? (
        <p className="mt-2 rounded-md border border-emerald-200 bg-emerald-50 px-3 py-1.5 text-xs text-emerald-800">
          {t("restored")}
        </p>
      ) : null}

      <div className="mt-4 grid gap-3 sm:grid-cols-[180px_1fr]">
        <ul className="space-y-1">
          {files.map((f) => (
            <li key={f.path}>
              <button
                type="button"
                onClick={() => selectFile(f.path)}
                className={`w-full truncate rounded px-2 py-1 text-left font-mono text-xs ${
                  f.path === active?.path ? "bg-stone-900 text-white" : "text-ink hover:bg-stone-100"
                }`}
                title={f.path}
              >
                {f.path}
              </button>
            </li>
          ))}
        </ul>
        <textarea
          value={active?.contents ?? ""}
          onChange={(e) => active && onEdit(active.path, e.target.value)}
          onPaste={(e) => {
            // Record paste MAGNITUDE (char count) only — not the content. A single
            // large bulk paste into the watched editor is the in-product
            // paste-from-LLM tell the authenticity scorer now penalizes.
            const n = (e.clipboardData?.getData("text") ?? "").length;
            if (active && n > 0) record("paste", active.path, n);
          }}
          spellCheck={false}
          className="focus-ring h-80 w-full resize-y rounded-md border border-stone-200 bg-stone-50 p-3 font-mono text-xs leading-relaxed text-ink caret-coral"
          aria-label={active?.path ?? "editor"}
        />
      </div>

      <div className="mt-4 grid gap-3 sm:grid-cols-2">
        <label className="block text-sm font-medium text-ink">
          {tApply("fieldName")} <span className="text-coral">*</span>
          <TextInput value={name} onChange={(e) => setName(e.target.value)} className="mt-1" />
        </label>
        <label className="block text-sm font-medium text-ink">
          {tApply("fieldContact")} <span className="text-coral">*</span>
          <TextInput
            type="email"
            value={contact}
            onChange={(e) => setContact(e.target.value)}
            placeholder={tApply("fieldContactPlaceholder")}
            className="mt-1"
          />
          <span className="mt-1 block text-xs font-normal text-steel">{tApply("fieldContactHint")}</span>
        </label>
      </div>
      <div className="mt-4 flex items-center gap-3">
        <button
          type="button"
          onClick={submit}
          disabled={!canSubmit}
          className="rounded-md bg-stone-900 px-4 py-2 text-sm font-medium text-white hover:bg-stone-800 disabled:cursor-not-allowed disabled:opacity-60"
        >
          {status === "submitting" ? t("submitting") : t("submit")}
        </button>
        {status === "error" ? <span className="text-sm text-red-700">{t("error")}</span> : null}
      </div>
    </section>
  );
}

// Live Work Surface — local draft persistence (verifier pass, 2026-07-17).
//
// Pure encode/decode helpers, kept free of `window`/`localStorage` so they run
// under node:test with no DOM. LiveWorkSurface.tsx is the only caller that
// actually touches `localStorage`, guarded by `typeof window !== "undefined"`.
//
// WHY THIS EXISTS: the surface already flushes to the server every FLUSH_MS and
// re-buffers a batch in memory (pendingRef) when a flush fails — but that buffer,
// and the `files` React state itself, live ONLY in memory. A reload, a crashed
// tab, or a laptop that sleeps through a flaky-wifi gap loses everything back to
// the frozen seed, even though most of the work was never actually gone — it just
// never survived a page life-cycle event. This module is the client-side durable
// copy: written on every meaningful change, read once on mount to resume.
import type { ProcessEvent, SeedFile } from "@/app/features/sub_dev/DevTypes";

// Mirror the server's own bounds (app/api/devcase/session/[id]/route.ts) so a
// corrupted/tampered localStorage blob can't blow up the tab or smuggle an
// oversized payload into the next flush. Local storage is candidate-writable,
// so treat it exactly like other client input: parse defensively, never trust.
const MAX_FILES = 50;
const MAX_FILE_BYTES = 256 * 1024;
const MAX_PENDING_EVENTS = 2000;
const KINDS = new Set<ProcessEvent["kind"]>(["open", "edit", "decision_log", "submit", "paste"]);

export type LiveWorkDraft = {
  sessionId: string | null;
  files: SeedFile[];
  pending: ProcessEvent[];
  savedAt: number;
};

export function draftStorageKey(token: string): string {
  return `kp:devcase:livework:${token}`;
}

export function encodeDraft(draft: LiveWorkDraft): string {
  return JSON.stringify(draft);
}

/** Defensively parse a stored draft. Returns null on anything malformed rather
 *  than throwing — a bad blob must fall back to the frozen seed, never crash
 *  the work surface. */
export function decodeDraft(raw: string | null | undefined): LiveWorkDraft | null {
  if (!raw) return null;
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== "object") return null;
  const p = parsed as Record<string, unknown>;

  const sessionId = typeof p.sessionId === "string" && p.sessionId ? p.sessionId : null;

  const files: SeedFile[] = Array.isArray(p.files)
    ? p.files
        .filter(
          (f): f is SeedFile =>
            !!f && typeof f === "object" && typeof (f as SeedFile).path === "string" && typeof (f as SeedFile).contents === "string"
        )
        .slice(0, MAX_FILES)
        .map((f) => ({ path: f.path, contents: f.contents.slice(0, MAX_FILE_BYTES) }))
    : [];

  const pending: ProcessEvent[] = Array.isArray(p.pending)
    ? p.pending
        .filter((e): e is Record<string, unknown> => !!e && typeof e === "object")
        .filter((e) => KINDS.has(String(e.kind) as ProcessEvent["kind"]))
        .slice(0, MAX_PENDING_EVENTS)
        .map((e) => {
          const ev: ProcessEvent = { t: Number(e.t) || 0, kind: String(e.kind) as ProcessEvent["kind"] };
          if (typeof e.path === "string") ev.path = e.path;
          if (Number.isFinite(Number(e.size))) ev.size = Number(e.size);
          return ev;
        })
    : [];

  const savedAt = Number.isFinite(Number(p.savedAt)) ? Number(p.savedAt) : 0;

  if (files.length === 0 && pending.length === 0 && !sessionId) return null;
  return { sessionId, files, pending, savedAt };
}

// Live Work Surface — local draft persistence, verifier pass 2026-07-17.
// Pure logic (no DOM): run with node:test directly, no jsdom needed.
import { test } from "node:test";
import assert from "node:assert/strict";
import { draftStorageKey, encodeDraft, decodeDraft, type LiveWorkDraft } from "./liveWorkDraft.ts";

test("draftStorageKey is namespaced and per-token", () => {
  assert.equal(draftStorageKey("tok-a"), "kp:devcase:livework:tok-a");
  assert.notEqual(draftStorageKey("tok-a"), draftStorageKey("tok-b"));
});

test("round-trips a normal draft", () => {
  const draft: LiveWorkDraft = {
    sessionId: "dsess_1",
    files: [{ path: "src/index.ts", contents: "export const x = 1;\n" }],
    pending: [{ t: 1000, kind: "edit", path: "src/index.ts" }],
    savedAt: 1000,
  };
  const decoded = decodeDraft(encodeDraft(draft));
  assert.deepEqual(decoded, draft);
});

test("decodeDraft returns null for missing/garbage input", () => {
  assert.equal(decodeDraft(null), null);
  assert.equal(decodeDraft(undefined), null);
  assert.equal(decodeDraft(""), null);
  assert.equal(decodeDraft("not json"), null);
  assert.equal(decodeDraft("42"), null);
  assert.equal(decodeDraft("null"), null);
});

test("decodeDraft returns null for an empty-but-present draft (nothing worth resuming)", () => {
  assert.equal(decodeDraft(JSON.stringify({ sessionId: null, files: [], pending: [], savedAt: 1 })), null);
});

test("decodeDraft drops unknown event kinds and non-object files (candidate-writable storage)", () => {
  const raw = JSON.stringify({
    sessionId: "dsess_2",
    files: [{ path: "a.ts", contents: "ok" }, { path: "bad" }, "not-a-file", 42],
    pending: [
      { t: 1, kind: "edit", path: "a.ts" },
      { t: 2, kind: "eval", path: "a.ts" }, // not a real ProcessEventKind
      "not-an-event",
    ],
    savedAt: 5,
  });
  const decoded = decodeDraft(raw);
  assert.ok(decoded);
  assert.deepEqual(decoded!.files, [{ path: "a.ts", contents: "ok" }]);
  assert.deepEqual(decoded!.pending, [{ t: 1, kind: "edit", path: "a.ts" }]);
});

test("decodeDraft caps oversized file contents and file/event counts (mirrors the server route's bounds)", () => {
  const bigContents = "x".repeat(300 * 1024); // over the 256KB cap
  const manyFiles = Array.from({ length: 60 }, (_, i) => ({ path: `f${i}.ts`, contents: "x" }));
  const manyEvents = Array.from({ length: 2500 }, (_, i) => ({ t: i, kind: "edit", path: "a.ts" }));
  const raw = JSON.stringify({
    sessionId: "dsess_3",
    files: [{ path: "big.ts", contents: bigContents }, ...manyFiles],
    pending: manyEvents,
    savedAt: 1,
  });
  const decoded = decodeDraft(raw);
  assert.ok(decoded);
  assert.equal(decoded!.files.length, 50, "capped at MAX_FILES");
  assert.ok(decoded!.files[0].contents.length <= 256 * 1024, "capped at MAX_FILE_BYTES");
  assert.equal(decoded!.pending.length, 2000, "capped at MAX_PENDING_EVENTS");
});
